 static UniversalRenderPipelineAsset Pipeline(){string folder="Assets/TruckBaseJumping/Rendering/";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var source=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/TruckCheeseRolling/Rendering/Cheese pipeline.asset");if(source==null){var path=AssetDatabase.FindAssets("t:UniversalRenderPipelineAsset",new[]{"Assets/TruckCheeseRolling/Rendering"}).Select(AssetDatabase.GUIDToAssetPath).First();source=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(path);}var original=new SerializedObject(source).FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue as ScriptableRendererData;var renderer=UnityEngine.Object.Instantiate(original);renderer.name="Base Jumping Weather Maker renderer";string rendererPath=folder+"Base renderer.asset";var existing=AssetDatabase.LoadAssetAtPath<ScriptableRendererData>(rendererPath);if(existing!=null){UnityEngine.Object.DestroyImmediate(renderer);renderer=existing;}else{AssetDatabase.CreateAsset(renderer,rendererPath);var features=original.rendererFeatures.ToArray();renderer.rendererFeatures.Clear();foreach(var feature in features){if(feature==null||feature.GetType().Name.Contains("Mushroom"))continue;var copy=UnityEngine.Object.Instantiate(feature);copy.name=feature.name;AssetDatabase.AddObjectToAsset(copy,renderer);renderer.rendererFeatures.Add(copy);}EditorUtility.SetDirty(renderer);}var pipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(folder+"Base pipeline.asset");if(pipeline==null){pipeline=UnityEngine.Object.Instantiate(source);pipeline.name="Base Jumping scoped weather pipeline";AssetDatabase.CreateAsset(pipeline,folder+"Base pipeline.asset");}var so=new SerializedObject(pipeline);var list=so.FindProperty("m_RendererDataList");list.arraySize=1;list.GetArrayElementAtIndex(0).objectReferenceValue=renderer;so.FindProperty("m_DefaultRendererIndex").intValue=0;so.ApplyModifiedPropertiesWithoutUndo();return pipeline;}
 static Mesh Canopy(){string path="Assets/TruckBaseJumping/Materials/Parachute canopy.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);int sides=24,rings=5;var vertices=new List<Vector3>();var uv=new List<Vector2>();var colored=new List<int>();var white=new List<int>();for(int r=0;r<=rings;r++)for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides,t=r/(float)rings;vertices.Add(new Vector3(Mathf.Cos(a)*4.8f*t,2.5f*Mathf.Sqrt(Mathf.Max(0,1-t*t)),Mathf.Sin(a)*3.6f*t));uv.Add(new Vector2(i/(float)sides,t));}for(int r=0;r<rings;r++)for(int i=0;i<sides;i++){int a=r*(sides+1)+i,b=a+1,c=a+sides+1,d=c+1;var target=(i/3)%2==0?colored:white;target.AddRange(new[]{a,c,b,b,c,d});}var mesh=new Mesh{name="Domed striped parachute"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.subMeshCount=2;mesh.SetTriangles(colored,0);mesh.SetTriangles(white,1);mesh.SetNormals(vertices.Select(v=>new Vector3(v.x/(4.8f*4.8f),v.y/(2.5f*2.5f),v.z/(3.6f*3.6f)).normalized).ToList());mesh.RecalculateBounds();if(existing==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);return existing;}
 static GameObject Shape(string name,PrimitiveType type,Transform parent,Vector3 p,Vector3 s,Material material){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=material;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static AudioClip Rotor(){string path="Assets/TruckBaseJumping/Audio/Helicopter rotor.wav";if(!File.Exists(path)){const int rate=22050,n=44100;var random=new System.Random(7919);using(var w=new BinaryWriter(File.Create(path))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+n*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(n*2);float low=0;for(int i=0;i<n;i++){float t=i/(float)rate;low=Mathf.Lerp(low,(float)random.NextDouble()*2-1,.025f);float blades=.3f+.7f*Mathf.Pow(.5f+.5f*Mathf.Sin(2*Mathf.PI*18*t),5);float sample=(Mathf.Sin(2*Mathf.PI*72*t)*.13f+low*.65f)*blades;w.Write((short)(sample*short.MaxValue));}}}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);return AssetDatabase.LoadAssetAtPath<AudioClip>(path);}
 public static void Create(){Directory.CreateDirectory("Assets/TruckBaseJumping/Prefabs");AssetDatabase.Refresh();EditorSceneManager.OpenScene(LWS.TruckCheeseRolling.Editor.CheeseAuthoring.Scene);var cheese=UnityEngine.Object.FindAnyObjectByType<CheeseMatch>();var clips=cheese.feedback.clips.Concat(new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBowling/Audio/Winner.wav")}).ToArray();var blast=UnityEngine.Object.Instantiate(cheese.explosions[0].gameObject);var explosion=PrefabUtility.SaveAsPrefabAsset(blast,"Assets/TruckBaseJumping/Prefabs/Crash blast.prefab");UnityEngine.Object.DestroyImmediate(blast);
  var m=SportsEventAuthoring.Begin<BaseJumpMatch>(Folder);m.setup.count=4;m.feedback.clips=clips;var green=SportsEventAuthoring.Mat(Folder,"Landing meadow",new Color(.15f,.25f,.13f));var dark=SportsEventAuthoring.Mat(Folder,"Helicopter graphite",new Color(.065f,.09f,.075f),.6f);var glass=SportsEventAuthoring.Mat(Folder,"Helicopter glass",new Color(.08f,.25f,.32f),.9f);var white=SportsEventAuthoring.Mat(Folder,"Canopy ivory",new Color(.95f,.95f,.86f));var mint=SportsEventAuthoring.Mat(Folder,"Target beacon",new Color(.2f,1,.6f));mint.EnableKeyword("_EMISSION");mint.SetColor("_EmissionColor",new Color(.2f,1,.6f)*5);var groundPhysics=SportsEventAuthoring.Contact(Folder,"Landing surface",.5f,.06f);m.ground=SportsEventAuthoring.Box("Landing field",new Vector3(0,-.5f,0),new Vector3(330,1,330),green,groundPhysics).GetComponent<Collider>();m.target=new GameObject("First-contact target reference").transform;m.target.position=Vector3.zero;
  var circle=new GameObject("Marked landing zone").AddComponent<LineRenderer>();circle.useWorldSpace=true;circle.sharedMaterial=mint;circle.positionCount=97;circle.startWidth=circle.endWidth=.25f;for(int i=0;i<97;i++){float a=i*Mathf.PI*2/96;circle.SetPosition(i,new Vector3(Mathf.Cos(a)*m.targetRadius,.035f,Mathf.Sin(a)*m.targetRadius));}SportsEventAuthoring.Box("Target center north-south",new Vector3(0,.028f,0),new Vector3(.3f,.04f,7),white);SportsEventAuthoring.Box("Target center east-west",new Vector3(0,.03f,0),new Vector3(7,.04f,.3f),white);
  for(int i=0;i<12;i++){float a=i*Mathf.PI/6;var p=new Vector3(Mathf.Cos(a)*18,0,Mathf.Sin(a)*18);Shape("Perimeter light",PrimitiveType.Cylinder,null,p+Vector3.up*.5f,new Vector3(.25f,.5f,.25f),mint);var light=new GameObject("Target beacon light").AddComponent<Light>();light.type=LightType.Point;light.transform.position=p+Vector3.up;light.range=7;light.intensity=6;light.color=new Color(.3f,1,.6f);light.shadows=LightShadows.None;if(i%2==0){var smoke=new GameObject("Perimeter colored smoke").AddComponent<ParticleSystem>();smoke.transform.position=p;var main=smoke.main;main.loop=true;main.startLifetime=3;main.startSpeed=1.5f;main.startSize=1.7f;main.startColor=new Color(.2f,.9f,.45f,.3f);main.maxParticles=30;var emission=smoke.emission;emission.rateOverTime=5;var shape=smoke.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=12;shape.radius=.2f;var material=SportsEventAuthoring.Mat(Folder,"Target smoke",new Color(.2f,.9f,.45f,.3f));material.shader=Shader.Find("Universal Render Pipeline/Particles/Unlit");material.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture>("Assets/WeatherMaker/Prefab/Textures/Clouds/WeatherMakerCloudSpriteSheet1.png"));material.SetFloat("_Surface",1);material.SetFloat("_Blend",2);material.SetInt("_SrcBlend",(int)BlendMode.SrcAlpha);material.SetInt("_DstBlend",(int)BlendMode.One);material.SetInt("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=(int)RenderQueue.Transparent;material.SetOverrideTag("RenderType","Transparent");EditorUtility.SetDirty(material);var sheet=smoke.textureSheetAnimation;sheet.enabled=true;sheet.numTilesX=sheet.numTilesY=4;sheet.frameOverTime=new ParticleSystem.MinMaxCurve(0);smoke.GetComponent<ParticleSystemRenderer>().sharedMaterial=material;}}
  BaseJumpTransportAuthoring.Install(m);m.rotorAudio=m.gameObject.AddComponent<AudioSource>();m.rotorAudio.clip=Rotor();m.rotorAudio.loop=true;m.rotorAudio.playOnAwake=false;
  white.SetInt("_Cull",0);var mesh=Canopy();m.jumpers=new BaseJumper[4];for(int i=0;i<4;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Parachute truck "+(i+1),m.transport.Stage(i),i);t.body.maxLinearVelocity=70;t.body.maxAngularVelocity=3;var j=t.gameObject.AddComponent<BaseJumper>();j.truck=t;j.match=m;j.slot=i;m.jumpers[i]=j;var canopy=new GameObject("Parachute canopy "+i,typeof(MeshFilter),typeof(MeshRenderer));canopy.GetComponent<MeshFilter>().sharedMesh=mesh;canopy.GetComponent<Renderer>().sharedMaterials=new[]{SportsEventAuthoring.Mat(Folder,"Canopy participant "+i,m.setup.players[i].color),white};foreach(var material in canopy.GetComponent<Renderer>().sharedMaterials){material.SetInt("_Cull",0);EditorUtility.SetDirty(material);}j.canopy=canopy.transform;j.lines=new LineRenderer[4];for(int k=0;k<4;k++){var line=new GameObject("Parachute harness "+i+" / "+k).AddComponent<LineRenderer>();line.positionCount=2;line.startWidth=line.endWidth=.035f;line.sharedMaterial=white;line.enabled=false;j.lines[k]=line;}canopy.SetActive(false);var fx=(GameObject)PrefabUtility.InstantiatePrefab(explosion);j.crash=fx.GetComponent<ParticleSystem>();}
  m.views=new SportsEventCamera[4];m.cameras=new Camera[4];for(int i=0;i<4;i++){m.views[i]=SportsEventAuthoring.Camera("Base Jumping view "+i);m.cameras[i]=m.views[i].view;m.cameras[i].enabled=i==0;m.cameras[i].farClipPlane=1200;m.views[i].Pose(new Vector3(0,264,-54),new Vector3(27,17,-38),62,true);var data=m.cameras[i].GetUniversalAdditionalCameraData();data.SetRenderer(0);data.renderPostProcessing=true;data.volumeLayerMask=1<<31;}
  Weather(m);m.gameObject.AddComponent<BaseJumpRendering>().pipeline=Pipeline();BaseSkyAuthoring.Install(m);SportsEventAuthoring.UI(m);SportsEventAuthoring.Save(Folder);Validate();}
 static void Weather(BaseJumpMatch m){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/WeatherMaker/Prefab/WeatherMakerPrefab.prefab");var world=(GameObject)PrefabUtility.InstantiatePrefab(prefab);PrefabUtility.UnpackPrefabInstance(world,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);world.name="Base Jumping scene-owned Weather Maker";var w=m.gameObject.AddComponent<BaseJumpWeather>();m.weatherField=w;w.match=m;w.vendor=world.GetComponentInChildren<WeatherMakerScript>(true);w.vendor.IsPermanent=false;w.precipitation=world.GetComponentInChildren<WeatherMakerPrecipitationManagerScript>(true);w.wind=world.GetComponentInChildren<WeatherMakerWindScript>(true);w.sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include).First(l=>l.type==LightType.Directional);w.vendor.AutoFindMainCamera=false;w.vendor.AllowCameras.Clear();w.vendor.AllowCameras.Add(m.cameras[0]);var resources=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<WeatherMakerResourceContainerScript>("Assets/WeatherMaker/Prefab/Profiles/ResourceContainer/WeatherMakerResourceContainerScript_NoWater.asset"));resources.Shaders.RemoveAll(s=>s!=null&&s.name.IndexOf("Water",StringComparison.OrdinalIgnoreCase)>=0);resources.ProfilesWater.Clear();string resourcePath="Assets/TruckBaseJumping/Materials/Base weather resources.asset";var existing=AssetDatabase.LoadAssetAtPath<WeatherMakerResourceContainerScript>(resourcePath);if(existing==null){AssetDatabase.CreateAsset(resources,resourcePath);existing=resources;}else{EditorUtility.CopySerialized(resources,existing);UnityEngine.Object.DestroyImmediate(resources);}w.vendor.ResourceContainer=existing;
  var windProfile=UnityEngine.Object.Instantiate(w.wind.WindProfile);windProfile.WindMaximumChangeRotation.Minimum=windProfile.WindMaximumChangeRotation.Maximum=0;windProfile.WindChangeInterval.Minimum=windProfile.WindChangeInterval.Maximum=0;windProfile.WindSpeedRange.Minimum=windProfile.WindSpeedRange.Maximum=1;windProfile.WindMainMultiplier=14;windProfile.AutoWindIntensity=false;string windPath="Assets/TruckBaseJumping/Materials/Shared wind profile.asset";var ownedWind=AssetDatabase.LoadAssetAtPath<WeatherMakerWindProfileScript>(windPath);if(ownedWind==null){AssetDatabase.CreateAsset(windProfile,windPath);ownedWind=windProfile;}else{EditorUtility.CopySerialized(windProfile,ownedWind);UnityEngine.Object.DestroyImmediate(windProfile);}w.wind.WindProfile=ownedWind;
  var day=world.GetComponentInChildren<WeatherMakerDayNightCycleManagerScript>(true);var profile=UnityEngine.Object.Instantiate(day.DayNightProfile);profile.Speed=profile.NightSpeed=0;profile.TimeOfDay=43200;string dayPath="Assets/TruckBaseJumping/Materials/Fixed daylight.asset";var ownedDay=AssetDatabase.LoadAssetAtPath<WeatherMakerDayNightCycleProfileScript>(dayPath);if(ownedDay==null){AssetDatabase.CreateAsset(profile,dayPath);ownedDay=profile;}else{EditorUtility.CopySerialized(profile,ownedDay);UnityEngine.Object.DestroyImmediate(profile);}day.DayNightProfile=ownedDay;
  var volume=new GameObject("Target beacon bloom").AddComponent<Volume>();volume.gameObject.layer=31;volume.isGlobal=true;var grade=ScriptableObject.CreateInstance<VolumeProfile>();var bloom=grade.Add<Bloom>();bloom.active=true;bloom.intensity.Override(.6f);bloom.threshold.Override(1.1f);string volumePath="Assets/TruckBaseJumping/Materials/Base weather grade.asset";var previous=AssetDatabase.LoadAssetAtPath<VolumeProfile>(volumePath);if(previous==null){AssetDatabase.CreateAsset(grade,volumePath);AssetDatabase.AddObjectToAsset(bloom,grade);previous=grade;}else UnityEngine.Object.DestroyImmediate(grade);if(previous.TryGet<Bloom>(out var ownedBloom)){ownedBloom.intensity.Override(.14f);ownedBloom.threshold.Override(1.1f);ownedBloom.clamp.Override(2);EditorUtility.SetDirty(ownedBloom);}volume.sharedProfile=previous;
  w.ambience=m.gameObject.AddComponent<AudioSource>();w.ambience.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Wind/WeatherMakerWindSound1.mp3");if(w.ambience.clip==null)w.ambience.clip=AssetDatabase.FindAssets("t:AudioClip",new[]{"Assets/WeatherMaker/Prefab/Sound"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.IndexOf("Wind",StringComparison.OrdinalIgnoreCase)>=0).Select(AssetDatabase.LoadAssetAtPath<AudioClip>).FirstOrDefault();w.ambience.loop=true;w.ambience.playOnAwake=false;}
 public static void Validate(){Fixtures();EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<BaseJumpMatch>();if(m==null||m.jumpers.Length!=4||m.cameras.Length!=4||m.weatherField.vendor==null||m.GetComponent<BaseJumpRendering>().pipeline==null||m.jumpers.Any(j=>j.lines.Length!=4||j.canopy==null)||UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Base Jumping saved references invalid");if(m.jumpers[0].canopy.GetComponent<MeshFilter>().sharedMesh.normals.Any(n=>n.sqrMagnitude<.9f))throw new Exception("Canopy smooth normals invalid");if(m.weatherField.vendor.IsPermanent)throw new Exception("Scene weather must not persist");Debug.Log("BASE_SAVED_VALIDATED");}
 public static void Fixtures(){int n=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Base fixture: "+label);n++;};var a=new BaseLanding{valid=true,inside=true,errorMillimetres=15500,timeMilliseconds=50000};var b=new BaseLanding{valid=true,inside=false,errorMillimetres=16500,timeMilliseconds=10000};check(BaseJumpRules.Compare(a,b)<0,"inside outranks outside regardless of speed");a.errorMillimetres=999;b.inside=true;b.errorMillimetres=1000;b.timeMilliseconds=1000;check(BaseJumpRules.Compare(a,b)<0,"accuracy band precedes time");a.errorMillimetres=900;a.timeMilliseconds=20000;b.errorMillimetres=100;b.timeMilliseconds=21000;check(BaseJumpRules.Compare(a,b)<0,"same band faster first");a.timeMilliseconds=b.timeMilliseconds;a.errorMillimetres=99;check(BaseJumpRules.Compare(a,b)<0,"exact millimetre tiebreak");var results=new[]{a,b,new BaseLanding{valid=false},new BaseLanding{valid=false}};var order=new int[4];BaseJumpRules.Rank(results,order);check(results[0].points==4&&results[1].points==3&&results[2].points==0,"placement points/invalid zero");check(BaseJumpRules.Winner(new[]{4,3,2,1},new int[4],new int[4])==0,"highest overall points");check(BaseJumpRules.Winner(new[]{4,4,2,1},new[]{100,90,0,0},new int[4])==1,"overall valid error tiebreak");check(BaseJumpRules.Winner(new[]{4,4,2,1},new[]{100,100,0,0},new[]{1000,900,0,0})==1,"overall valid time tiebreak");check(BaseJumpRules.Winner(new[]{4,4,2,1},new[]{100,100,0,0},new[]{1000,1000,0,0})==-1,"overall exact tie requests another round");check(BaseJumpRules.Safe(true,1,new Vector3(0,-6,0),Vector3.up)&&!BaseJumpRules.Safe(false,0,new Vector3(0,-6,0),Vector3.up)&&!BaseJumpRules.Safe(true,1,new Vector3(0,-12,0),Vector3.up),"actual incoming safe envelope");for(int i=0;i<4;i++)check(Mathf.Abs(BaseJumpMatch.ReleasePosition(i).y-260)<.001f&&Mathf.Abs(new Vector2(BaseJumpMatch.ReleasePosition(i).x,BaseJumpMatch.ReleasePosition(i).z).magnitude-55)<.001f,"equal release altitude/range "+i);Debug.Log("BASE_RULE_FIXTURES_PASS count="+n);}
